type SettingsServiceServer interface {
	GetSettings(context.Context, *GetSettingsRequest) (*GetSettingsResponse, error)
	UpdateSettings(context.Context, *UpdateSettingsRequest) (*UpdateSettingsResponse, error)
	// 绑定面板域名（为空表示取消），自动申请正式证书。节点的控制连接和安装命令仍然用 IP:端口 + 公钥指纹。
	SetPanelDomain(context.Context, *SetPanelDomainApiRequest) (*UpdateSettingsResponse, error)
	GetAlertConfig(context.Context, *GetAlertConfigRequest) (*GetAlertConfigResponse, error)
	UpdateAlertConfig(context.Context, *UpdateAlertConfigRequest) (*UpdateAlertConfigResponse, error)
	// 用面板发一条测试消息到某个渠道。
	TestAlertChannel(context.Context, *TestAlertChannelRequest) (*TestAlertChannelResponse, error)
	// 生成接入码：其他面板用它把节点交给本面板。1 小时内可以给多个节点用。
	CreateInvite(context.Context, *CreateInviteRequest) (*CreateInviteResponse, error)
	// 还在有效期内的接入码。
	ListInvites(context.Context, *ListInvitesRequest) (*ListInvitesResponse, error)
	// 提前作废接入码。
	RevokeInvite(context.Context, *RevokeInviteRequest) (*RevokeInviteResponse, error)
	// 账号安全：两步验证和安全入口。
	GetSecurity(context.Context, *GetSecurityRequest) (*Security, error)
	// 开始设置两步验证：返回密钥和验证器 App 扫码用的地址，10 分钟内用 EnableTOTP 确认。
	BeginTOTP(context.Context, *BeginTOTPRequest) (*BeginTOTPResponse, error)
	EnableTOTP(context.Context, *EnableTOTPRequest) (*Security, error)
	// 关闭两步验证，需要当前的验证码或者密码。
	DisableTOTP(context.Context, *DisableTOTPRequest) (*Security, error)
	// 开启（生成新的随机路径）或关闭安全入口。
	SetEntrance(context.Context, *SetEntranceRequest) (*Security, error)
	mustEmbedUnimplementedSettingsServiceServer()
}

